/* ---------- Sidebar ---------- */
.gsb.gc { gap: 14px; width: 240px; padding: 12px; border-radius: min(var(--glass-radius), 22px); }
.gsb[data-collapsed] { width: 64px; align-items: center; }
.gsb-nav { display: flex; flex-direction: column; gap: 14px; }
.gsb-sec { display: flex; flex-direction: column; gap: 2px; }
.gsb-label { padding: 0 10px 4px; font-size: 11.5px; font-weight: 600; letter-spacing: 0.02em; text-transform: uppercase; color: rgb(var(--glass-shadow) / 0.5); }
.gsb-item { position: relative; display: flex; align-items: center; gap: 10px; width: 100%; min-height: 36px; padding: 0 10px; border: 0; border-radius: min(var(--glass-radius), 10px); background: none; font: inherit; font-size: 14px; color: rgb(var(--glass-shadow) / 0.75); text-align: left; cursor: pointer; transition: background 0.15s, color 0.15s; }
.gsb[data-collapsed] .gsb-item { justify-content: center; width: 40px; padding: 0; }
.gsb-item:hover { background: rgb(var(--glass-shadow) / 0.06); color: var(--glass-fg); }
