.gsb-item:focus-visible { outline: 2px solid var(--glass-focus, var(--glass-tint)); outline-offset: -2px; }
.gsb-icon { display: inline-flex; flex: none; }
.gsb-icon svg { width: 18px; height: 18px; }
.gsb-text { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.gsb-count { flex: none; min-width: 20px; padding: 1px 7px; border-radius: 999px; font-size: 11.5px; font-weight: 600; text-align: center; color: var(--glass-on-tint); background: var(--glass-tint); }
.gsb-head, .gsb-foot { display: flex; align-items: center; gap: 10px; }
.gsb-foot { margin-top: auto; padding-top: 10px; border-top: 1px solid rgb(var(--glass-shadow) / 0.08); }

/* ---------- Charts ---------- */
.gch { position: relative; width: 100%; color: var(--glass-fg); }
