.gch-cursor { stroke: rgb(var(--glass-shadow) / 0.25); stroke-dasharray: 3 3; vector-effect: non-scaling-stroke; }
.gch-dot { fill: var(--c); stroke: var(--gch-bg, #fff); stroke-width: 2; }
[data-glass-mode="dark"] .gch-dot { --gch-bg: #1c1c20; }
