.gch [data-series="3"], .gdn [data-series="3"] { --c: var(--gch-3); }
.gch-tip { position: absolute; top: 4px; transform: translateX(-50%); display: flex; flex-direction: column; gap: 2px; padding: 8px 10px; border-radius: 10px; font-size: 12px; white-space: nowrap; pointer-events: none; color: #fff; background: rgb(28 28 32 / 0.92); box-shadow: 0 8px 20px -8px rgb(0 0 0 / 0.4); }
.gch-tip span, .gch-legend span { display: inline-flex; align-items: center; gap: 6px; }
.gch-tip i, .gch-legend i, .gdn-legend i { width: 8px; height: 8px; border-radius: 2px; background: var(--c); }
.gch-tip b { margin-left: auto; padding-left: 12px; }
.gch-legend { display: flex; gap: 16px; margin-top: 8px; font-size: 12.5px; color: rgb(var(--glass-shadow) / 0.7); }
.gsp-line { fill: none; stroke: var(--sp, var(--gch-0)); stroke-width: 1.8; stroke-linecap: round; }
.gsp-area { fill: var(--sp, var(--gch-0)); opacity: 0.18; -webkit-mask-image: linear-gradient(#000, transparent); mask-image: linear-gradient(#000, transparent); }
.gsp[data-tone="good"] { --sp: var(--gch-good); }
.gsp[data-tone="bad"] { --sp: var(--gch-bad); }
.gdn { display: flex; align-items: center; gap: 22px; flex-wrap: wrap; color: var(--glass-fg); }
.gdn svg { flex: none; transform: rotate(-90deg); }
.gdn svg text { transform: rotate(90deg); transform-origin: 64px 64px; }
.gdn-track { fill: none; stroke: rgb(var(--glass-shadow) / 0.08); stroke-width: 14; }
.gdn-part { fill: none; stroke: var(--c); stroke-width: 14; stroke-linecap: butt; }
.gdn-total { font-size: 20px; font-weight: 600; fill: var(--glass-fg); font-family: inherit; }
.gdn-label { font-size: 10px; fill: rgb(var(--glass-shadow) / 0.55); font-family: inherit; }
.gdn-legend { display: flex; flex-direction: column; gap: 8px; margin: 0; padding: 0; list-style: none; font-size: 13.5px; }
.gdn-legend li { display: flex; align-items: center; gap: 8px; }
.gdn-legend b { margin-left: auto; padding-left: 16px; font-weight: 600; font-variant-numeric: tabular-nums; }

/* ---------- Stat card ---------- */
.gst.gc { gap: 10px; padding: 18px 20px; }
.gst-label { font-size: 13px; font-weight: 500; color: rgb(var(--glass-shadow) / 0.62); }
.gst-row { display: flex; align-items: flex-end; justify-content: space-between; gap: 12px; min-width: 0; }
.gst-row > .gsp { flex: 0 1 96px; min-width: 40px; }
.gst-value { white-space: nowrap; }
.gst-value { font-size: 28px; font-weight: 600; letter-spacing: -0.03em; font-variant-numeric: tabular-nums; line-height: 1.1; }
.gst-foot { display: flex; align-items: center; gap: 8px; font-size: 12.5px; color: rgb(var(--glass-shadow) / 0.55); }
.gst-change { display: inline-flex; align-items: center; gap: 2px; padding: 2px 7px 2px 4px; border-radius: 999px; font-weight: 600; color: var(--gch-bad); background: color-mix(in srgb, var(--gch-bad) 12%, transparent); }
.gst-change[data-good] { color: var(--gch-good); background: color-mix(in srgb, var(--gch-good) 12%, transparent); }

/* ---------- Data table ---------- */
.gdt { display: flex; flex-direction: column; gap: 10px; min-width: 0; color: var(--glass-fg); }
.gdt-bar { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; min-height: 40px; }
.gdt-search { flex: 1; min-width: 180px; max-width: 320px; }
.gdt-tools { display: flex; gap: 8px; margin-left: auto; }
.gdt-bulk { display: flex; align-items: center; gap: 12px; width: 100%; padding: 6px 8px 6px 14px; border-radius: min(var(--glass-radius), 14px); font-size: 14px; background: color-mix(in srgb, var(--glass-tint) 10%, transparent); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--glass-tint) 25%, transparent); animation: gdt-in 0.2s cubic-bezier(0.2, 0.8, 0.2, 1); }
@keyframes gdt-in { from { opacity: 0; transform: translateY(-4px); } }
.gdt-bulk-actions { display: flex; gap: 8px; margin-left: auto; }
.gdt-clear { border: 0; background: none; font: inherit; font-size: 13px; color: rgb(var(--glass-shadow) / 0.65); cursor: pointer; }
.gdt .gtb th, .gdt .gtb td { padding-block: 10px; }
.gdt-cell-check { width: 44px; padding-right: 0 !important; }
.gdt-cell-actions { width: 52px; text-align: right; }
.gdt-check { gap: 0; }
.gdt-check .gck { width: 18px; height: 18px; }
.gdt-check .gck svg { width: 12px; height: 12px; }
.gdt-sort { display: inline-flex; align-items: center; gap: 4px; padding: 0; border: 0; background: none; font: inherit; color: inherit; cursor: pointer; }
.gdt-sort svg { opacity: 0.25; }
.gdt-sort svg[data-on] { opacity: 1; color: var(--glass-fg); }
.gdt tr[data-selected] td { background: color-mix(in srgb, var(--glass-tint) 7%, transparent); }
.gdt-empty { padding: 36px 16px !important; text-align: center; color: rgb(var(--glass-shadow) / 0.6); }
.gdt-foot { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; font-size: 13px; color: rgb(var(--glass-shadow) / 0.6); }
.gpg { display: inline-flex; align-items: center; gap: 4px; }
.gpg-btn { display: grid; place-items: center; min-width: 32px; height: 32px; padding: 0 8px; border: 0; border-radius: min(var(--glass-radius), 9px); background: none; font: inherit; font-size: 13px; font-variant-numeric: tabular-nums; color: var(--glass-fg); cursor: pointer; }
.gpg-btn:hover:not(:disabled) { background: rgb(var(--glass-shadow) / 0.07); }
.gpg-btn[aria-current="page"] { font-weight: 600; color: var(--glass-on-tint); background: var(--glass-tint); }
.gpg-btn:disabled { opacity: 0.35; cursor: default; }
.gpg-gap { padding: 0 2px; color: rgb(var(--glass-shadow) / 0.5); }
[data-glass-tint="frost"] .gpg-btn[aria-current="page"] { color: #262d3a; background: linear-gradient(180deg, #f6f8fb, #dfe4ec); box-shadow: inset 0 1px 0 #fff, 0 0 0 0.5px rgb(70 82 104 / 0.25); }

/* ---------- Command menu ---------- */
.gcmd.gdl { width: min(560px, calc(100vw - 32px)); max-height: min(520px, 80vh); margin-top: 12vh; padding: 10px; display: none; flex-direction: column; gap: 8px; }
.gcmd.gdl[open] { display: flex; }
.gcmd-search { --gf-h: 46px; }
.gcmd-esc { flex: none; padding: 2px 6px; border-radius: 6px; font-size: 11px; font-family: inherit; color: rgb(var(--glass-shadow) / 0.6); background: rgb(var(--glass-shadow) / 0.07); }
.gcmd-list { overflow-y: auto; padding: 2px; }
.gcmd-group { padding: 10px 10px 4px; font-size: 11.5px; font-weight: 600; letter-spacing: 0.02em; text-transform: uppercase; color: rgb(var(--glass-shadow) / 0.5); }
.gcmd-item { display: flex; align-items: center; gap: 10px; min-height: 40px; padding: 0 10px; border-radius: min(var(--glass-radius), 10px); font-size: 14px; cursor: pointer; }
.gcmd-item[aria-selected="true"] { background: rgb(var(--glass-shadow) / 0.08); }
.gcmd-icon { display: inline-flex; opacity: 0.7; }
.gcmd-icon svg { width: 17px; height: 17px; }
.gcmd-text { flex: 1; min-width: 0; display: flex; gap: 8px; align-items: baseline; }
.gcmd-hint { font-size: 12.5px; color: rgb(var(--glass-shadow) / 0.5); }
.gcmd-keys { display: inline-flex; gap: 3px; }
.gcmd-keys kbd { min-width: 20px; padding: 1px 6px; border-radius: 5px; font-family: inherit; font-size: 11.5px; text-align: center; color: rgb(var(--glass-shadow) / 0.7); background: rgb(var(--glass-shadow) / 0.07); box-shadow: inset 0 -1px 0 rgb(var(--glass-shadow) / 0.12); }
.gcmd-empty { padding: 26px 10px; margin: 0; text-align: center; font-size: 14px; color: rgb(var(--glass-shadow) / 0.6); }

/* ---------- Drawer ---------- */
.gdr.gdl { position: fixed; inset: 0 0 0 auto; width: min(440px, 100vw); max-width: none; height: 100%; max-height: none; margin: 0; padding: 0; border-radius: 24px 0 0 24px; display: none; flex-direction: column; }
.gdr.gdl[open] { display: flex; animation: gdr-in 0.32s cubic-bezier(0.2, 0.8, 0.2, 1); }
.gdr[data-side="left"].gdl { inset: 0 auto 0 0; border-radius: 0 24px 24px 0; }
.gdr[data-side="left"].gdl[open] { animation-name: gdr-in-left; }
@keyframes gdr-in { from { transform: translateX(40px); opacity: 0; } }
@keyframes gdr-in-left { from { transform: translateX(-40px); opacity: 0; } }
.gdr-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; padding: 22px 22px 14px; border-bottom: 1px solid rgb(var(--glass-shadow) / 0.08); }
.gdr-body { flex: 1; overflow-y: auto; display: flex; flex-direction: column; gap: 16px; padding: 20px 22px; }
.gdr-foot { display: flex; justify-content: flex-end; gap: 10px; padding: 14px 22px; border-top: 1px solid rgb(var(--glass-shadow) / 0.08); }

/* ---------- Toasts ---------- */
.gts-wrap { position: fixed; z-index: 60; display: flex; flex-direction: column; gap: 10px; width: min(380px, calc(100vw - 32px)); pointer-events: none; }
.gts-wrap[data-position="bottom-right"] { right: 20px; bottom: 96px; }
.gts-wrap[data-position="top-right"] { right: 20px; top: 70px; }
.gts-wrap[data-position="bottom-center"] { left: 50%; bottom: 96px; transform: translateX(-50%); }
.gtst.gp { position: relative; top: auto; left: auto; display: flex; align-items: flex-start; gap: 10px; width: 100%; max-width: none; max-height: none; padding: 12px 10px 12px 14px; border-radius: min(var(--glass-radius), 16px); pointer-events: auto; animation: gtst-in 0.36s cubic-bezier(0.34, 1.4, 0.5, 1); transition: opacity 0.2s, transform 0.2s; color: var(--glass-fg); }
.gtst[data-leaving] { opacity: 0; transform: translateX(16px) scale(0.98); }
