.gtst-mark { display: grid; place-items: center; flex: none; width: 22px; height: 22px; margin-top: 1px; border-radius: 50%; color: #fff; background: rgb(var(--glass-shadow) / 0.55); }
.gtst-mark svg { width: 14px; height: 14px; stroke-width: 2.4; }
.gtst[data-tone="success"] .gtst-mark { background: #17a065; }
.gtst[data-tone="danger"] .gtst-mark { background: #d12c3a; }
.gtst-body { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; font-size: 14px; }
.gtst-body span { font-size: 13px; color: rgb(var(--glass-shadow) / 0.65); }
.gtst-action { flex: none; align-self: center; padding: 5px 10px; border: 0; border-radius: 8px; font: inherit; font-size: 13px; font-weight: 600; color: var(--glass-fg); background: rgb(var(--glass-shadow) / 0.08); cursor: pointer; }

/* ---------- Empty state and skeleton ---------- */
.gem { display: flex; flex-direction: column; align-items: center; gap: 8px; padding: 36px 20px; text-align: center; color: var(--glass-fg); }
.gem-icon { display: grid; place-items: center; width: 52px; height: 52px; margin-bottom: 6px; border-radius: 16px; color: var(--glass-fg); background: rgb(var(--glass-shadow) / 0.06); box-shadow: inset 0 0 0 1px rgb(var(--glass-shadow) / 0.08); }
.gem-icon svg { width: 24px; height: 24px; }
.gem-title { margin: 0; font-size: 17px; font-weight: 600; }
.gem-text { max-width: 36ch; margin: 0; font-size: 14px; color: rgb(var(--glass-shadow) / 0.62); }
.gem-actions { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-top: 10px; }
.gsk { display: block; background: linear-gradient(90deg, rgb(var(--glass-shadow) / 0.07) 25%, rgb(var(--glass-shadow) / 0.13) 45%, rgb(var(--glass-shadow) / 0.07) 65%) 0 0 / 300% 100%; animation: gsk 1.4s ease-in-out infinite; }
.gsk-lines { display: flex; flex-direction: column; gap: 8px; width: 100%; }
@keyframes gsk { from { background-position: 100% 0; } to { background-position: 0 0; } }

/* ---------- Date range ---------- */
.gdp { position: relative; }
.gdp-trigger { cursor: pointer; }
.gdp-pop.gp { display: flex; gap: 6px; width: auto; max-width: min(520px, 92vw); max-height: none; padding: 8px; }
.gdp-presets { display: flex; flex-direction: column; gap: 2px; min-width: 120px; padding-right: 6px; border-right: 1px solid rgb(var(--glass-shadow) / 0.08); }
.gdp-preset { padding: 7px 10px; border: 0; border-radius: 8px; background: none; font: inherit; font-size: 13.5px; text-align: left; color: var(--glass-fg); cursor: pointer; }
.gdp-preset:hover { background: rgb(var(--glass-shadow) / 0.07); }
.gdp-cal { padding: 2px 4px; color: var(--glass-fg); }
.gdp-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 6px; font-size: 14px; }
.gdp-grid { display: grid; grid-template-columns: repeat(7, 34px); gap: 2px 0; }
.gdp-dow { display: grid; place-items: center; height: 26px; font-size: 11.5px; color: rgb(var(--glass-shadow) / 0.5); }
.gdp-day { height: 34px; border: 0; border-radius: 9px; background: none; font: inherit; font-size: 13px; font-variant-numeric: tabular-nums; color: var(--glass-fg); cursor: pointer; }
.gdp-day:hover { background: rgb(var(--glass-shadow) / 0.08); }
.gdp-day[data-in] { border-radius: 0; background: color-mix(in srgb, var(--glass-tint) 14%, transparent); }
.gdp-day[data-edge] { font-weight: 600; color: var(--glass-on-tint); background: var(--glass-tint); }
.gdp-day[data-today]:not([data-edge]) { box-shadow: inset 0 0 0 1px rgb(var(--glass-shadow) / 0.3); }
.gdp-hint { margin: 8px 2px 2px; font-size: 12px; color: rgb(var(--glass-shadow) / 0.55); }
[data-glass-tint="frost"] .gdp-day[data-edge] { color: #262d3a; background: linear-gradient(180deg, #f6f8fb, #d9dfe8); box-shadow: inset 0 1px 0 #fff, 0 0 0 0.5px rgb(70 82 104 / 0.3); }
@media (max-width: 520px) { .gdp-pop.gp { flex-direction: column; } .gdp-presets { flex-direction: row; flex-wrap: wrap; border-right: 0; padding: 0 0 6px; border-bottom: 1px solid rgb(var(--glass-shadow) / 0.08); } }

/* ---------- Stepper ---------- */
.gstp { position: relative; display: flex; gap: 8px; margin: 0; padding: 0; list-style: none; color: var(--glass-fg); }
.gstp[data-orientation="horizontal"] .gstp-step { display: flex; align-items: flex-start; gap: 10px; flex: 1; min-width: 0; }
.gstp[data-orientation="horizontal"] .gstp-step:last-child { flex: none; }
.gstp[data-orientation="horizontal"] .gstp-step:not(:last-child)::after { content: ""; flex: 1; min-width: 12px; height: 2px; margin-top: 14px; border-radius: 2px; background: rgb(var(--glass-shadow) / 0.12); transition: background 0.3s; }
.gstp[data-orientation="horizontal"] .gstp-step[data-state="done"]::after { background: var(--glass-tint); }
.gstp[data-orientation="horizontal"] .gstp-text { white-space: nowrap; }
.gstp[data-orientation="vertical"] { flex-direction: column; gap: 4px; }
.gstp[data-orientation="vertical"] .gstp-step { position: relative; padding-bottom: 14px; }
.gstp[data-orientation="vertical"] .gstp-step:not(:last-child)::after { content: ""; position: absolute; left: 14px; top: 34px; bottom: 2px; width: 2px; border-radius: 2px; background: rgb(var(--glass-shadow) / 0.12); }
.gstp[data-orientation="vertical"] .gstp-step[data-state="done"]::after { background: var(--glass-tint); }
.gstp-btn { display: flex; align-items: flex-start; gap: 10px; padding: 0; border: 0; background: none; font: inherit; color: inherit; text-align: left; }
button.gstp-btn { cursor: pointer; }
.gstp-mark { display: grid; place-items: center; flex: none; width: 30px; height: 30px; border-radius: 50%; font-size: 13px; font-weight: 600; color: rgb(var(--glass-shadow) / 0.6); background: var(--gstp-bg, #fff); box-shadow: inset 0 0 0 1.5px rgb(var(--glass-shadow) / 0.2); transition: background 0.25s, color 0.25s, box-shadow 0.25s; }
.gstp-step[data-state="current"] .gstp-mark { color: var(--glass-fg); box-shadow: inset 0 0 0 2px var(--glass-tint), 0 0 0 4px color-mix(in srgb, var(--glass-tint) 18%, transparent); }
.gstp-step[data-state="done"] .gstp-mark { color: var(--glass-on-tint); background: var(--glass-tint); box-shadow: none; }
.gstp-text { display: flex; flex-direction: column; gap: 1px; padding-top: 5px; font-size: 14px; font-weight: 500; }
.gstp-step[data-state="todo"] .gstp-text { color: rgb(var(--glass-shadow) / 0.55); }
.gstp-hint { font-size: 12.5px; font-weight: 400; color: rgb(var(--glass-shadow) / 0.55); }
[data-glass-mode="dark"] .gstp-mark { --gstp-bg: #1c1c20; }
[data-glass-tint="frost"] .gstp-step[data-state="done"] .gstp-mark { color: #262d3a; background: linear-gradient(180deg, #f6f8fb, #d9dfe8); box-shadow: inset 0 1px 0 #fff, 0 0 0 0.5px rgb(70 82 104 / 0.3); }
/* When the row is too narrow for every label, only the current step keeps its name */
.gstp[data-orientation="horizontal"] { container-type: inline-size; width: 100%; }
@container (max-width: 560px) { .gstp-text { display: none; } .gstp-step[data-state="current"] .gstp-text { display: flex; } .gstp-step[data-state="current"] { flex: none; } }

@media (prefers-reduced-motion: reduce) {
  .gsk, .gtst, .gdr.gdl[open], .gdt-bulk { animation: none; }
}

/* Stepper on a dark picture */
[data-glass-on="dark"] .gstp { color: #fff; }
[data-glass-on="dark"] .gstp-mark { --gstp-bg: rgb(255 255 255 / 0.14); color: #fff; box-shadow: inset 0 0 0 1.5px rgb(255 255 255 / 0.45); -webkit-backdrop-filter: blur(10px); backdrop-filter: blur(10px); }
[data-glass-on="dark"] .gstp-step[data-state="current"] .gstp-mark { color: #fff; box-shadow: inset 0 0 0 2px #fff, 0 0 0 4px rgb(255 255 255 / 0.2); }
[data-glass-on="dark"] .gstp-step[data-state="done"] .gstp-mark { color: var(--glass-on-tint); background: var(--glass-tint); box-shadow: none; }
[data-glass-on="dark"] .gstp-step[data-state="todo"] .gstp-text, [data-glass-on="dark"] .gstp-hint { color: rgb(255 255 255 / 0.72); }
[data-glass-on="dark"] .gstp-step:not(:last-child)::after { background: rgb(255 255 255 / 0.3); }
[data-glass-on="dark"] [data-glass-tint="frost"] .gstp-step[data-state="done"] .gstp-mark, [data-glass-tint="frost"] [data-glass-on="dark"] .gstp-step[data-state="done"] .gstp-mark { color: #262d3a; background: linear-gradient(180deg, #f6f8fb, #d9dfe8); }
[data-glass-on="dark"] .gdp-day[data-in], [data-glass-mode="dark"] .gdp-day[data-in] { background: rgb(255 255 255 / 0.12); }
[data-glass-mode="dark"] [data-glass-tint="frost"] :is(.gch, .gdn, .gsp, .gst), [data-glass-mode="dark"][data-glass-tint="frost"] :is(.gch, .gdn) { --gch-0: #d3d9e3; --gch-1: #8b95a5; --gch-2: #586273; --gch-3: #f1f3f6; }
